<div class="page-heading"><div><div class="eyebrow">SCHOOL FINANCES</div><h1>Mini Finance Book<span class="green">.</span></h1><p>Student payments appear automatically as income. Record other income and expenses here.</p></div><button class="button primary" data-open="finance-dialog">Add entry</button></div>
<section class="panel"><form method="get" class="filters"><?php input('From','from','date',$from,false); input('To','to','date',$to,false); ?><button class="button">Apply dates</button><a class="text-link" href="<?= e(url('finance')) ?>">All dates</a></form></section>
<div class="stats-grid three section-gap"><?php foreach([['Income',$income],['Expenses (outcome)',$expenses],['Profit',$income-$expenses]] as [$label,$value]): ?><div class="stat-card"><span><?= e($label) ?></span><strong><?= money($value/100) ?></strong></div><?php endforeach ?></div>
<section class="panel"><div class="panel-heading"><div><h2>Finance entries</h2><p>Profit is collected income minus recorded expenses for the selected dates.</p></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Reference</th><th>Type</th><th>Description</th><th>Category</th><th>Amount</th></tr></thead><tbody><?php foreach($entries as $entry): ?><tr><td><?= e($entry['occurred_on']) ?></td><td><?php if($entry['invoice_id']): ?><a class="text-link" target="_blank" rel="noopener" href="<?= e(url('invoices/'.$entry['invoice_id'].'/print')) ?>"><?= e($entry['reference']) ?></a><?php else: ?><?= e($entry['reference']) ?><?php endif ?></td><td><span class="badge <?= $entry['type']==='Income'?'success':'warning' ?>"><?= e($entry['type']) ?></span></td><td><?= e($entry['description']) ?></td><td><?= e($entry['category']) ?></td><td><?= money($entry['amount']) ?></td></tr><?php endforeach ?><?php if(!$entries): ?><tr><td colspan="6" class="empty">No finance entries for these dates.</td></tr><?php endif ?></tbody></table></div></section>
<dialog id="finance-dialog" <?= !empty($_SESSION['old'])?'data-auto-open':'' ?>><div class="dialog-heading"><h2>Add finance entry</h2><button class="icon-button" data-close aria-label="Close">×</button></div><form method="post" action="<?= e(url('learning/finance')) ?>"><?= csrf_field() ?><div class="form-grid"><?php choose('Type','type',['Income'=>'Income','Expense'=>'Expense (outcome)']); input('Description','description'); input('Category','category'); input('Amount','amount','number'); input('Date','occurred_on','date',date('Y-m-d')); ?></div><div class="form-footer"><button type="button" class="button" data-close>Cancel</button><button class="button primary">Save entry</button></div></form></dialog>
